    pub fn is_constructor(&self) -> bool {
        match &self.borrow().kind {
            ObjKind::Closure(c) => c.code.is_constructor(),
            ObjKind::Native(n) => n.is_ctor,
            ObjKind::Bound(b) => b.target.is_constructor(),
            ObjKind::Proxy(p) => p.constructor,
            _ => false,
        }
    }
