74	/// Add Likely Subtags: the (language, script, region) the original's
75	/// `maximize` produces, or None when nothing is known for the language (the
76	/// tag is then left unchanged).
77	pub fn maximize_fields(lang: &str, script: Option<&str>, region: Option<&str>) -> Option<(String, String, String)> {
78	    let own = |l: &str, s: &str, r: &str| Some((l.to_string(), s.to_string(), r.to_string()));
79	    if lang == "und" {
80	        return match (script, region) {
81	            (Some(s), Some(r)) => {
82	                let l = if let Some(l) = lookup2(data::UND_SCRIPT_REGION, &format!("{}-{}", s, r)) {
83	                    l
84	                } else if let Some((l, _)) = lookup3(data::UND_REGION, r) {
85	                    l
86	                } else if let Some((l, _)) = lookup3(data::UND_SCRIPT, s) {
87	                    l
88	                } else {
89	                    "en"
90	                };
91	                own(l, s, r)
92	            }
93	            (Some(s), None) => match lookup3(data::UND_SCRIPT, s) {
94	                Some((l, r)) => own(l, s, r),
95	                None => own("en", s, "US"),
96	            },
97	            (None, Some(r)) => match lookup3(data::UND_REGION, r) {
98	                Some((l, s)) => own(l, s, r),
99	                None => own("en", "Latn", r),
100	            },
101	            (None, None) => own("en", "Latn", "US"),
102	        };
103	    }
104	    match (script, region) {
105	        (Some(s), Some(r)) => own(lang, s, r),
106	        (None, Some(r)) => {
107	            if let Some(s) = lookup2(data::LANG_REGION, &format!("{}-{}", lang, r)) {
108	                return own(lang, s, r);
109	            }
110	            lookup3(data::LANG, lang).and_then(|(s, _)| own(lang, s, r))
111	        }
112	        (Some(s), None) => {
113	            if let Some(r) = lookup2(data::LANG_SCRIPT, &format!("{}-{}", lang, s)) {
114	                return own(lang, s, r);
115	            }
116	            if let Some((_, r)) = lookup3(data::LANG, lang) {
117	                return own(lang, s, r);
118	            }
119	            // unknown language: the region of und-<script>
120	            lookup3(data::UND_SCRIPT, s).and_then(|(_, r)| own(lang, s, r))
121	        }
122	        (None, None) => lookup3(data::LANG, lang).and_then(|(s, r)| own(lang, s, r)),
123	    }
124	}
125	
126	/// Remove Likely Subtags (favouring the region): (language, script, region).
127	pub fn minimize_fields(
128	    lang: &str,
129	    script: Option<&str>,
130	    region: Option<&str>,
131	) -> (String, Option<String>, Option<String>) {
132	    let max = match maximize_fields(lang, script, region) {
133	        Some(m) => m,
134	        None => return (lang.to_string(), script.map(|s| s.to_string()), region.map(|s| s.to_string())),
135	    };
136	    let (ml, ms, mr) = (max.0.as_str(), max.1.as_str(), max.2.as_str());
137	    if maximize_fields(ml, None, None).as_ref() == Some(&max) {
138	        return (ml.to_string(), None, None);
139	    }
140	    if maximize_fields(ml, None, Some(mr)).as_ref() == Some(&max) {
141	        return (ml.to_string(), None, Some(mr.to_string()));
142	    }
143	    if maximize_fields(ml, Some(ms), None).as_ref() == Some(&max) {
144	        return (ml.to_string(), Some(ms.to_string()), None);
145	    }
146	    (ml.to_string(), Some(ms.to_string()), Some(mr.to_string()))
147	}
