157	/// Write the slots of a Locale object for the (canonical) tag.
158	fn write_slots(o: &Obj, t: &LangTag) {
159	    set_slot(o, "__locale_tag", Value::str(&t.to_canonical_string()));
160	    set_slot(o, "__locale_basename", Value::str(&t.base_name()));
161	    set_slot(o, "__locale_language", Value::str(&t.language));
162	    if let Some(s) = &t.script {
