167	    }
168	    if !t.variants.is_empty() {
169	        set_slot(o, "__locale_variants", Value::str(&t.variants.join("-")));
170	    }
171	    for (k, v) in &t.u_keywords {
172	        set_slot(o, &format!("__locale_{}", k), Value::str(v));
173	    }
174	}
