// Extract unit + compact pattern data from the original.
const keys = ['en','en-IN','ar','ar-MA','de','es','fr','gv','hi','it','ja','ko','ln','nl','pl','pt','pt-PT','ru','si','sl','sr','sv','th','zh','zh-TW'];
const units = Intl.supportedValuesOf('unit').concat(['kilometer-per-hour', 'meter-per-second']);
const samples = {
  default: {one: 1, other: 2},
  fr: {one: 1, other: 2, many: 1000000},
  pl: {one: 1, few: 2, many: 5, other: 1.5},
  sl: {one: 1, two: 2, few: 3, other: 5},
  gv: {one: 1, two: 2, few: 20, many: 1.5, other: 3},
  ja: {other: 2}, ko: {other: 2}, th: {other: 2}, zh: {other: 2},
};
const NUMS = /^(integer|group|decimal|fraction|minusSign|plusSign)$/;
function pattern(parts) {
  // replace the run of number parts by {0}
  const out = [];
  let inNum = false;
  for (const p of parts) {
    if (NUMS.test(p.type)) { if (!inNum) { out.push({type: 'NUM'}); inNum = true; } }
    else { out.push({type: p.type, value: p.value}); inNum = false; }
  }
  return out;
}
const result = {units: {}, compact: {}};
for (const k of keys) {
  const lang = k.split('-')[0];
  const sm = samples[lang] || samples.default;
  // sanity: check sample categories
  const pr = new Intl.PluralRules(k);
  for (const c in sm) if (pr.select(sm[c]) !== c) throw new Error('bad sample ' + k + ' ' + c);
  const u = {};
  for (const unit of units) {
    const d = {};
    for (const disp of ['short', 'long', 'narrow']) {
      const f = new Intl.NumberFormat(k, {style: 'unit', unit, unitDisplay: disp});
      const c = {};
      for (const cat in sm) c[cat] = pattern(f.formatToParts(sm[cat]));
      d[disp] = c;
    }
    u[unit] = d;
  }
  result.units[k] = u;
  const cp = {};
  for (const disp of ['short', 'long']) {
    const f = new Intl.NumberFormat(k, {notation: 'compact', compactDisplay: disp});
    const arr = [];
    for (let m = 0; m <= 22; m++) {
      const row = {};
      for (const mult of [1, 2, 1.5]) {
        const x = mult * Math.pow(10, m);
        const parts = f.formatToParts(x);
        row[String(mult)] = parts;
      }
      arr.push(row);
    }
    cp[disp] = arr;
  }
  result.compact[k] = cp;
}
console.log(JSON.stringify(result));

