//! Number formatting data of the original runtime (symbols, currencies,
//! compact patterns, numbering systems; unit patterns in `unitdata.rs`).

#[path = "unitdata.rs"]
mod unitdata;

/// Per-locale number formatting data.
#[derive(Clone, Copy, Debug)]
pub struct NumLocale {
    pub decimal: &'static str,
    pub group: &'static str,
    /// Indian grouping (3;2)
    pub indian: bool,
    pub percent_suffix: &'static str,
    /// currency symbol after the number ("1,00 €")
    pub currency_suffix: bool,
    pub nan: &'static str,
    /// symbol of USD with currencyDisplay "symbol"
    pub usd: &'static str,
    pub default_nu: &'static str,
    pub compact_short: &'static [(i32, &'static str)],
    pub compact_long: &'static [(i32, &'static str)],
    /// index into the unit pattern groups
    pub unit_group: usize,
}

const CS_DEFAULT: &[(i32, &str)] = &[(3, "K"), (6, "M"), (9, "B"), (12, "T")];
const CL_DEFAULT: &[(i32, &str)] = &[(3, " thousand"), (6, " million"), (9, " billion"), (12, " trillion")];
const CS_EN_IN: &[(i32, &str)] = &[(3, "K"), (5, "L"), (7, "Cr")];
const CS_DE: &[(i32, &str)] = &[(6, "\u{a0}Mio."), (9, "\u{a0}Mrd."), (12, "\u{a0}Bio.")];
const CL_DE: &[(i32, &str)] = &[(3, " Tausend"), (6, " Millionen"), (9, " Milliarden"), (12, " Billionen")];
const C_JA: &[(i32, &str)] = &[(4, "万"), (8, "億"), (12, "兆")];
const C_KO: &[(i32, &str)] = &[(3, "천"), (4, "만"), (8, "억"), (12, "조")];
const C_ZH: &[(i32, &str)] = &[(4, "万"), (8, "亿"), (12, "兆")];
const C_ZH_HANT: &[(i32, &str)] = &[(4, "萬"), (8, "億"), (12, "兆")];

fn unit_group_index(key: &str) -> usize {
    unitdata::UNIT_GROUPS.iter().position(|g| *g == key).unwrap_or(0)
}

/// Number data for a language + region.
pub fn num_locale(lang: &str, region: Option<&str>) -> NumLocale {
    let mut l = NumLocale {
        decimal: ".",
        group: ",",
        indian: false,
        percent_suffix: "%",
        currency_suffix: false,
        nan: "NaN",
        usd: "US$",
        default_nu: "latn",
        compact_short: CS_DEFAULT,
        compact_long: CL_DEFAULT,
        unit_group: 0,
    };
    let comma_dec = |l: &mut NumLocale, group: &'static str| {
        l.decimal = ",";
        l.group = group;
    };
    let mut ug = lang;
    match lang {
        "en" => {
            l.usd = "$";
            if region == Some("IN") {
                l.indian = true;
                l.compact_short = CS_EN_IN;
                ug = "en-IN";
            }
        }
        "ar" => {
            if !matches!(region, Some("DZ" | "EH" | "LY" | "MA" | "MR" | "TN")) {
                l.default_nu = "arab";
            }
        }
        "de" => {
            comma_dec(&mut l, ".");
            l.percent_suffix = "\u{a0}%";
            l.currency_suffix = true;
            l.usd = "$";
            l.compact_short = CS_DE;
            l.compact_long = CL_DE;
        }
        "es" | "it" | "nl" => comma_dec(&mut l, "."),
        "fr" | "ru" | "sv" => {
            comma_dec(&mut l, "\u{202f}");
            l.percent_suffix = "\u{a0}%";
            l.currency_suffix = true;
        }
        "pl" => {
            comma_dec(&mut l, "\u{a0}");
            l.percent_suffix = "\u{a0}%";
            l.currency_suffix = true;
        }
        "pt" => {
            comma_dec(&mut l, if region == Some("PT") { "\u{a0}" } else { "." });
            l.currency_suffix = true;
        }
        "hi" => l.indian = true,
        "ja" => {
            l.usd = "$";
            l.compact_short = C_JA;
            l.compact_long = C_JA;
        }
        "ko" => {
            l.compact_short = C_KO;
            l.compact_long = C_KO;
        }
        "zh" => {
            if matches!(region, Some("TW" | "HK" | "MO")) {
                l.nan = "非數值";
                l.compact_short = C_ZH_HANT;
                l.compact_long = C_ZH_HANT;
                ug = "zh-TW";
            } else {
                l.compact_short = C_ZH;
                l.compact_long = C_ZH;
            }
        }
        _ => {}
    }
    l.unit_group = unit_group_index(match ug {
        "ln" | "si" | "sr" | "sv" => "hi",
        other => other,
    });
    l
}

/// Fraction digits of a currency.
pub fn currency_digits(code: &str) -> u32 {
    match code {
        "BHD" | "IQD" | "JOD" | "KWD" | "LYD" | "OMR" | "TND" => 3,
        "CLP" | "DJF" | "GNF" | "HUF" | "ISK" | "JPY" | "KMF" | "KRW" | "PYG" | "RWF" | "TWD" | "UGX" | "VND" | "VUV"
        | "XAF" | "XOF" | "XPF" => 0,
        _ => 2,
    }
}

/// The text shown for a currency (`display`: symbol / narrowSymbol / name /
/// code).  Unknown currencies (and the code display) are the code followed
/// by a no-break space.
pub fn currency_symbol(code: &str, display: &str, loc: &NumLocale) -> String {
    if display == "code" {
        return format!("{}\u{a0}", code);
    }
    let s = match code {
        "USD" => {
            if display == "symbol" {
                loc.usd
            } else {
                "$"
            }
        }
        "EUR" => "€",
        "JPY" => "¥",
        "GBP" => "£",
        "CNY" => "CN¥",
        "CAD" => "CA$",
        "AUD" => "A$",
        _ => return format!("{}\u{a0}", code),
    };
    s.to_string()
}

/// Simple units (sanctioned by the original).
pub const SIMPLE_UNITS: [&str; 45] = [
    "acre", "bit", "byte", "celsius", "centimeter", "day", "degree", "fahrenheit", "fluid-ounce", "foot", "gallon",
    "gigabit", "gigabyte", "gram", "hectare", "hour", "inch", "kilobit", "kilobyte", "kilogram", "kilometer", "liter",
    "megabit", "megabyte", "meter", "microsecond", "mile", "mile-scandinavian", "milliliter", "millimeter",
    "millisecond", "minute", "month", "nanosecond", "ounce", "percent", "petabyte", "pound", "second", "stone",
    "terabit", "terabyte", "week", "yard", "year",
];

/// IsWellFormedUnitIdentifier.
pub fn is_well_formed_unit(u: &str) -> bool {
    if SIMPLE_UNITS.contains(&u) {
        return true;
    }
    match u.split_once("-per-") {
        Some((a, b)) => SIMPLE_UNITS.contains(&a) && SIMPLE_UNITS.contains(&b),
        None => false,
    }
}

/// Unit pattern ("{0} km") for a unit, display (short/long/narrow) and
/// whether the plural category is "one".
pub fn unit_pattern(loc: &NumLocale, unit: &str, display: &str, one: bool) -> String {
    let di = match display {
        "long" => 2,
        "narrow" => 4,
        _ => 0,
    } + if one { 0 } else { 1 };
    if let Some(ui) = unitdata::UNIT_IDS.iter().position(|u| *u == unit) {
        return unitdata::UNIT_PATTERNS[loc.unit_group][ui][di].to_string();
    }
    // generic fallback (compound units without data)
    match display {
        "long" => {
            let name = match unit.split_once("-per-") {
                Some((a, b)) => format!(
                    "{}{} per {}",
                    a.replace('-', " "),
                    if one { "" } else { "s" },
                    b.replace('-', " ")
                ),
                None => format!("{}{}", unit.replace('-', " "), if one { "" } else { "s" }),
            };
            format!("{{0}} {}", name)
        }
        "narrow" => format!("{{0}}{}", unit),
        _ => format!("{{0}} {}", unit),
    }
}

/// Decimal numbering systems: (name, code point of zero); hanidec is special.
pub const NUMBERING_SYSTEMS: &[(&str, u32)] = &[
    ("adlm", 0x1E950), ("ahom", 0x11730), ("arab", 0x0660), ("arabext", 0x06F0),
    ("bali", 0x1B50), ("beng", 0x09E6), ("bhks", 0x11C50), ("brah", 0x11066),
    ("cakm", 0x11136), ("cham", 0xAA50), ("chis", 0x16DA0), ("deva", 0x0966), ("diak", 0x11950),
    ("fullwide", 0xFF10), ("gara", 0x10D40), ("gong", 0x11DA0), ("gonm", 0x11D50),
    ("gujr", 0x0AE6), ("gukh", 0x16130), ("guru", 0x0A66), ("hanidec", 0),
    ("hmng", 0x16B50), ("hmnp", 0x1E140), ("java", 0xA9D0), ("kali", 0xA900),
    ("kawi", 0x11F50), ("khmr", 0x17E0), ("knda", 0x0CE6), ("krai", 0x16D70),
    ("lana", 0x1A80), ("lanatham", 0x1A90), ("laoo", 0x0ED0), ("latn", 0x30),
    ("lepc", 0x1C40), ("limb", 0x1946), ("mathbold", 0x1D7CE), ("mathdbl", 0x1D7D8),
    ("mathmono", 0x1D7F6), ("mathsanb", 0x1D7EC), ("mathsans", 0x1D7E2), ("mlym", 0x0D66),
    ("modi", 0x11650), ("mong", 0x1810), ("mroo", 0x16A60), ("mtei", 0xABF0),
    ("mymr", 0x1040), ("mymrepka", 0x116DA), ("mymrpao", 0x116D0), ("mymrshan", 0x1090),
    ("mymrtlng", 0xA9F0), ("nagm", 0x1E4F0), ("newa", 0x11450), ("nkoo", 0x07C0),
    ("olck", 0x1C50), ("onao", 0x1E5F1), ("orya", 0x0B66), ("osma", 0x104A0),
    ("outlined", 0x1CCF0), ("rohg", 0x10D30), ("saur", 0xA8D0), ("segment", 0x1FBF0),
    ("shrd", 0x111D0), ("sind", 0x112F0), ("sinh", 0x0DE6), ("sora", 0x110F0),
    ("sund", 0x1BB0), ("sunu", 0x11BF0), ("takr", 0x116C0), ("talu", 0x19D0),
    ("tamldec", 0x0BE6), ("telu", 0x0C66), ("thai", 0x0E50), ("tibt", 0x0F20),
    ("tirh", 0x114D0), ("tnsa", 0x16AC0), ("tols", 0x11DE0), ("vaii", 0xA620), ("wara", 0x118E0),
    ("wcho", 0x1E2F0),
];

pub const HANIDEC_DIGITS: [char; 10] = ['〇', '一', '二', '三', '四', '五', '六', '七', '八', '九'];

pub fn numbering_system_supported(nu: &str) -> bool {
    NUMBERING_SYSTEMS.iter().any(|(n, _)| *n == nu)
}

/// Replace ASCII digits by the digits of numbering system `nu`.
pub fn transliterate(s: &str, nu: &str) -> String {
    if nu == "latn" {
        return s.to_string();
    }
    let zero = match NUMBERING_SYSTEMS.iter().find(|(n, _)| *n == nu) {
        Some((_, z)) => *z,
        None => return s.to_string(),
    };
    s.chars()
        .map(|c| {
            if c.is_ascii_digit() {
                let d = c as u32 - '0' as u32;
                if nu == "hanidec" {
                    HANIDEC_DIGITS[d as usize]
                } else {
                    char::from_u32(zero + d).unwrap_or(c)
                }
            } else {
                c
            }
        })
        .collect()
}

/// Is `c` a decimal digit of some numbering system (for the parts tokenizer).
pub fn is_any_digit(c: char) -> bool {
    if c.is_ascii_digit() || HANIDEC_DIGITS.contains(&c) {
        return true;
    }
    let cp = c as u32;
    NUMBERING_SYSTEMS.iter().any(|(_, z)| *z != 0 && cp >= *z && cp <= *z + 9)
}

//! Intl.PluralRules.
//!
//! The original's rules: `fr`, `gv`, `pl` and `sl` follow CLDR; `ja ko th
//! zh` only have "other"; every other language (including `ar` and `ru`,
//! whose pluralCategories nevertheless list all CLDR categories) has "one"
//! for exactly 1 (no visible fraction digits) and "other" otherwise.  The
//! `type` (cardinal/ordinal) and all digit options are stored but ignored by
//! `select`, which looks at the raw number.  `selectRange(x, y)` is
//! `select(y)`.
//!
//! Slots: `__pr: true`, `__pr_locale`, `__pr_type`, `__pr_minint`,
//! `__pr_minfrac`, `__pr_maxfrac`, `__pr_notation`, `__pr_compactdisplay`,
//! `__pr_roundingmode`, then `__pr_minsig` / `__pr_maxsig` when given.

use super::decimal::Decimal;
use super::*;

pub fn setup(vm: &mut Vm, intl: &Obj) {
    define_class(
        vm,
        intl,
        "PluralRules",
        0,
        pr_ctor,
        &[
            Member::Method("select", 1, pr_select),
            Member::Method("selectRange", 2, pr_select_range),
            Member::Method("resolvedOptions", 0, pr_resolved_options),
        ],
        true,
    );
}

/// pluralCategories of a language.
pub fn plural_categories(lang: &str) -> &'static [&'static str] {
    match lang {
        "ar" => &["zero", "one", "two", "few", "many", "other"],
        "fr" => &["one", "many", "other"],
        "gv" => &["one", "two", "few", "many", "other"],
        "pl" | "ru" => &["one", "few", "many", "other"],
        "sl" => &["one", "two", "few", "other"],
        "ja" | "ko" | "th" | "zh" => &["other"],
        _ => &["one", "other"],
    }
}

/// i mod 10^k of the integer part of `d`.
fn int_mod(d: &Decimal, k: u32) -> u64 {
    let mut r: u64 = 0;
    let ip = d.point.max(0) as usize;
    let start = ip.saturating_sub(k as usize);
    for idx in start..ip {
        r = r * 10 + d.digits.get(idx).copied().unwrap_or(0) as u64;
    }
    r
}

fn int_is(d: &Decimal, v: u64) -> bool {
    // integer part equals v (v small)
    let ip = d.point.max(0) as usize;
    if ip > 20 {
        return false;
    }
    int_mod(d, 20) == v
}

/// Plural category of a decimal (absolute value; `v` = visible fraction
/// digits) under the original's rules.
pub fn plural_category_dec(lang: &str, d: &Decimal) -> &'static str {
    let v0 = d.is_integer();
    match lang {
        "ja" | "ko" | "th" | "zh" => "other",
        "fr" => {
            if int_is(d, 0) || int_is(d, 1) {
                "one"
            } else if v0 && d.point > 0 && int_mod(d, 6) == 0 && !int_is(d, 0) {
                "many"
            } else {
                "other"
            }
        }
        "gv" => {
            if !v0 {
                "many"
            } else if int_mod(d, 1) == 1 {
                "one"
            } else if int_mod(d, 1) == 2 {
                "two"
            } else if [0, 20, 40, 60, 80].contains(&int_mod(d, 2)) {
                "few"
            } else {
                "other"
            }
        }
        "pl" => {
            if !v0 {
                return "other";
            }
            let i10 = int_mod(d, 1);
            let i100 = int_mod(d, 2);
            if int_is(d, 1) {
                "one"
            } else if (2..=4).contains(&i10) && !(12..=14).contains(&i100) {
                "few"
            } else {
                "many"
            }
        }
        "sl" => {
            if !v0 {
                return "few";
            }
            match int_mod(d, 2) {
                1 => "one",
                2 => "two",
                3 | 4 => "few",
                _ => "other",
            }
        }
        _ => {
            if v0 && int_is(d, 1) {
                "one"
            } else {
                "other"
            }
        }
    }
}

/// Plural category of a JS number.
pub fn plural_category(lang: &str, x: f64) -> &'static str {
    if !x.is_finite() {
        return "other";
    }
    plural_category_dec(lang, &Decimal::from_f64(x))
}

fn pr_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    require_new(vm, a, "PluralRules")?;
    let locales = locale_list(vm, &a.arg(0))?;
    let opts = get_options(vm, &a.arg(1), OptionsMode::Strict)?;
    read_locale_matcher(vm, &opts)?;
    let ty = get_opt_str(vm, &opts, "type", &["cardinal", "ordinal"])?.unwrap_or_else(|| "cardinal".into());
    let notation = get_opt_str(vm, &opts, "notation", &["standard", "scientific", "engineering", "compact"])?
        .unwrap_or_else(|| "standard".into());
    let compact = get_opt_str(vm, &opts, "compactDisplay", &["short", "long"])?.unwrap_or_else(|| "short".into());
    let minint = get_opt_num(vm, &opts, "minimumIntegerDigits", 1.0, 21.0)?.unwrap_or(1.0);
    let minfrac = get_opt_num(vm, &opts, "minimumFractionDigits", 0.0, 100.0)?.unwrap_or(0.0);
    let maxfrac = get_opt_num(vm, &opts, "maximumFractionDigits", minfrac, 100.0)?.unwrap_or(minfrac.max(3.0));
    let mnsd = get_opt(vm, &opts, "minimumSignificantDigits")?;
    let mxsd = get_opt(vm, &opts, "maximumSignificantDigits")?;
    let mut sig = None;
    if !mnsd.is_undefined() || !mxsd.is_undefined() {
        let lo = num_in_range(vm, &mnsd, "minimumSignificantDigits", 1.0, 21.0, 1.0)?;
        let hi = num_in_range(vm, &mxsd, "maximumSignificantDigits", 1.0, 21.0, 21.0)?;
        sig = Some((lo, hi));
    }
    let _ = get_opt(vm, &opts, "roundingIncrement")?;
    let mode = get_opt_str(
        vm,
        &opts,
        "roundingMode",
        &["ceil", "floor", "expand", "trunc", "halfCeil", "halfFloor", "halfExpand", "halfTrunc", "halfEven"],
    )?
    .unwrap_or_else(|| "halfExpand".into());
    get_opt_str(vm, &opts, "roundingPriority", &["auto", "morePrecision", "lessPrecision"])?;
    get_opt_str(vm, &opts, "trailingZeroDisplay", &["auto", "stripIfInteger"])?;
    let r = resolve_locale(&locales);
    let o = alloc_instance(vm, a)?;
    set_slot(&o, "__pr", Value::Bool(true));
    set_slot(&o, "__pr_locale", Value::str(&r.base));
    set_slot(&o, "__pr_type", Value::str(&ty));
    set_slot(&o, "__pr_minint", Value::Num(minint));
    set_slot(&o, "__pr_minfrac", Value::Num(minfrac));
    set_slot(&o, "__pr_maxfrac", Value::Num(maxfrac));
    set_slot(&o, "__pr_notation", Value::str(&notation));
    set_slot(&o, "__pr_compactdisplay", Value::str(&compact));
    set_slot(&o, "__pr_roundingmode", Value::str(&mode));
    if let Some((lo, hi)) = sig {
        set_slot(&o, "__pr_minsig", Value::Num(lo));
        set_slot(&o, "__pr_maxsig", Value::Num(hi));
    }
    Ok(Value::Obj(o))
}

/// DefaultNumberOption-like read: undefined -> default; NaN or outside
/// [min, max] -> `RangeError: <name> out of range`.
fn num_in_range(vm: &mut Vm, v: &Value, name: &str, min: f64, max: f64, default: f64) -> JsResult<f64> {
    if v.is_undefined() {
        return Ok(default);
    }
    let n = vm.to_number(v)?;
    if n.is_nan() || n < min || n > max {
        return vm.throw_range(format!("{} out of range", name));
    }
    Ok(n.floor())
}

fn pr_lang(o: &Obj) -> String {
    let loc = slot_str(o, "__pr_locale").unwrap_or_else(|| "en".to_string());
    match parse_tag(&loc) {
        Some(t) => t.language,
        None => "en".to_string(),
    }
}

fn pr_select(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = branded_this(vm, &a.this, "__pr")?;
    let n = vm.to_number(&a.arg(0))?;
    Ok(Value::str(plural_category(&pr_lang(&o), n)))
}

fn pr_select_range(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = branded_this(vm, &a.this, "__pr")?;
    let (s, e) = (a.arg(0), a.arg(1));
    if s.is_undefined() || e.is_undefined() {
        return vm.throw_type("selectRange requires two numbers");
    }
    let x = vm.to_number(&s)?;
    let y = vm.to_number(&e)?;
    if x.is_nan() || y.is_nan() {
        return vm.throw_range("selectRange arguments must not be NaN");
    }
    Ok(Value::str(plural_category(&pr_lang(&o), y)))
}

fn pr_resolved_options(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = branded_this(vm, &a.this, "__pr")?;
    let r = vm.new_object();
    let copy = |r: &Obj, key: &str, name: &str| {
        if let Some(v) = slot(&o, name) {
            if !v.is_undefined() {
                r.set_str(key, v, WEC);
            }
        }
    };
    copy(&r, "locale", "__pr_locale");
    copy(&r, "type", "__pr_type");
    copy(&r, "notation", "__pr_notation");
    if slot_str(&o, "__pr_notation").as_deref() == Some("compact") {
        copy(&r, "compactDisplay", "__pr_compactdisplay");
    }
    copy(&r, "minimumIntegerDigits", "__pr_minint");
    copy(&r, "minimumFractionDigits", "__pr_minfrac");
    copy(&r, "maximumFractionDigits", "__pr_maxfrac");
    copy(&r, "minimumSignificantDigits", "__pr_minsig");
    copy(&r, "maximumSignificantDigits", "__pr_maxsig");
    let cats: Vec<String> = plural_categories(&pr_lang(&o)).iter().map(|s| s.to_string()).collect();
    let arr = str_array(vm, &cats);
    r.set_str("pluralCategories", arr, WEC);
    copy(&r, "roundingMode", "__pr_roundingmode");
    Ok(Value::Obj(r))
}

//! Intl.NumberFormat (and Number/BigInt.prototype.toLocaleString).
//!
//! Internal slots (own data properties, in this order): `__nf: true`,
//! `__nf_locale`, `__nf_nu`, `__nf_roundingincrement`,
//! `__nf_roundingpriority`, `__nf_trailingzero`, `__nf_style`, then for
//! currency `__nf_currency`, `__nf_currencydisplay`, `__nf_currencysign`,
//! when a unit was given `__nf_unit`, `__nf_unitdisplay`, then
//! `__nf_minint`, `__nf_minfrac`, `__nf_maxfrac`, [`__nf_minsig`,
//! `__nf_maxsig`], `__nf_notation`, `__nf_compactdisplay`, `__nf_grouping`,
//! `__nf_signdisplay`, `__nf_roundingmode`, `__nf_roundingtype`; the bound
//! `format` is cached in `__nf_boundformat`.
//!
//! Formatting follows ECMA-402 (exact decimal rounding of the shortest
//! round-trip digits, strings and BigInts exactly) with the original's data
//! (see numdata.rs) and quirks:
//! * compact notation ignores fraction-digit settings (2 significant digits,
//!   morePrecision) and never re-buckets (999999 -> "1000K");
//! * scientific/engineering take the exponent of the unrounded value
//!   ("10E0" for 9.9999), zero has no exponent, exponent digits are ASCII;
//! * formatToParts tokenizes the formatted string: any "E" starts the
//!   exponent (currency codes like EUR!), text before the number is the
//!   currency, text after it is split into leading spaces (literal) and the
//!   rest (currency / compact), percent suffixes are one percentSign part
//!   and text after the exponent belongs to exponentInteger.

use super::decimal::{Decimal, RoundingMode};
use super::numdata::{self, NumLocale};
use super::*;
use std::cell::RefCell;

pub fn setup(vm: &mut Vm, intl: &Obj) {
    let (c, _) = define_class(
        vm,
        intl,
        "NumberFormat",
        0,
        nf_ctor,
        &[
            Member::Getter("format", nf_format_getter),
            Member::Method("formatToParts", 1, nf_format_to_parts),
            Member::Method("resolvedOptions", 0, nf_resolved_options),
            Member::Method("formatRange", 2, nf_format_range),
            Member::Method("formatRangeToParts", 2, nf_format_range_to_parts),
        ],
        true,
    );
    NF_CTOR.with(|s| *s.borrow_mut() = Some(c));
}

thread_local! {
    static NF_CTOR: RefCell<Option<Obj>> = RefCell::new(None);
}

fn nf_ctor_obj() -> Obj {
    NF_CTOR.with(|s| s.borrow().clone().unwrap())
}

