const units = ['second','minute','hour','day','week','month','quarter','year'];
const samples = {en: {one: 1, other: 2}, pl: {one: 1, few: 2, many: 5, other: 1.5}};
const out = {};
for (const lang of ['en', 'pl']) {
  out[lang] = {};
  for (const style of ['long', 'short', 'narrow']) {
    const f = new Intl.RelativeTimeFormat(lang, {style});
    out[lang][style] = {};
    for (const u of units) {
      const e = {};
      for (const cat in samples[lang]) {
        const n = samples[lang][cat];
        for (const [dir, v] of [['past', -n], ['future', n]]) {
          const parts = f.formatToParts(v, u);
          let pat = '';
          let inNum = false;
          for (const p of parts) {
            if (p.unit !== undefined) { if (!inNum) { pat += '{0}'; inNum = true; } }
            else { pat += p.value; inNum = false; }
          }
          e[dir + '_' + cat] = pat;
        }
      }
      out[lang][style][u] = e;
    }
  }
}
// auto phrases
const auto = {};
for (const style of ['long', 'short', 'narrow']) {
  const f = new Intl.RelativeTimeFormat('en', {style, numeric: 'auto'});
  auto[style] = {};
  for (const u of units) {
    auto[style][u] = [-1, 0, 1].map(v => { const p = f.formatToParts(v, u); return p.length === 1 && p[0].type === 'literal' ? p[0].value : null; });
  }
}
out.auto = auto;
console.log(JSON.stringify(out, null, 1));

