const units = ['second','seconds','minute','minutes','hour','hours','day','days','week','weeks','month','months','quarter','quarters','year','years'];
function val() {
  const r = rnd();
  if (r < 0.1) return pick([0, -0, 1, -1, 2, -2, 5, 22, 12, 1.5, -1.5]);
  if (r < 0.15) return pick(['3', '-2.5', '1e3', ' 7 ']);
  const mag = Math.floor(rnd() * 12) - 4;
  let x = rnd() * Math.pow(10, mag);
  if (rnd() < 0.5) x = Math.round(x);
